import json
def transform(g):
    from collections import deque
    h,w=len(g),len(g[0]); seen=set(); regs=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==0 and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                regs.append(cells)
    regs.sort(key=len)
    out=[row[:] for row in g]
    for y,x in regs[0]: out[y][x]=7
    for y,x in regs[-1]: out[y][x]=8
    return out
